@code {
    private string activeSection = "Profile";

    // Toast
    private string? toastMessage;
    private string toastType = "toast-success";

    // Profile
    private UserProfile? profile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string editDisplayAvatarUrl = "";

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<string> editMutedChannels = new();
    private readonly List<string> allChannels = new() { "general", "announcements", "marketing", "engineering", "design", "random" };

    // Security
    private SecuritySettings? security;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool editTwoFactor;
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? appearance;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section)
    {
        activeSection = section;
        DismissToast();
    }

    private void ShowToast(string message, bool isError = false)
    {
        toastMessage = message;
        toastType = isError ? "toast-error" : "toast-success";
    }

    private void DismissToast() => toastMessage = null;

    // Profile methods
    private async Task LoadProfile()
    {
        profile = await SettingsService.GetProfileAsync();
        ResetProfileFields();
    }

    private void ResetProfileFields()
    {
        if (profile is null) return;
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editBio = profile.Bio;
        editDisplayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editDisplayAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.");
    }

    // Notification methods
    private async Task LoadNotifications()
    {
        notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        editEmailNotifications = notificationPrefs.EmailNotifications;
        editPushNotifications = notificationPrefs.PushNotifications;
        editWeeklyDigest = notificationPrefs.WeeklyDigest;
        editMutedChannels = new List<string>(notificationPrefs.MutedChannels);
    }

    private bool IsChannelMuted(string channel) => editMutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !editMutedChannels.Contains(channel))
            editMutedChannels.Add(channel);
        else if (!muted)
            editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, new List<string>(editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
        ShowToast("Notification preferences saved!");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        security = await SettingsService.GetSecuritySettingsAsync();
        editTwoFactor = security.TwoFactorEnabled;
    }

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", true);
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            await LoadSecurity();
            ShowToast($"Session on {sessionToRevoke.Device} revoked.");
        }
        CancelRevoke();
    }

    // Appearance methods
    private async Task LoadAppearance()
