}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact mode */
.preview-compact .preview-header,
.preview-compact .preview-body,
.preview-compact .preview-sidebar {
    padding: 0.4rem 0.6rem;
}

.preview-compact {
    min-height: 100px;
}

